function GiftPackComponent:GetItemNum(ItemID)
    if ItemID == Week_Card_Gift_Pack_Item_ID then
        return UGCBackpackSystemV2.GetItemCountV2(self:GetOwner(), Week_Card_Backpack_Item_ID)
    end

